custom_css:
/* Author: @jiuyi0204 | Usage notice is stored in the import JSON. */

/* Author: @jiuyi0204 | 夜百合铜章色卡与字体。未经许可禁止二次修改、二次上传或重新打包。 */
@font-face {
  font-family: "YBTC Source Han Serif SC";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

@font-face {
  font-family: "YBTC Huiwen Mincho";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/huiwenmincho-improved/HuiwenMincho-Improved-Regular.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

:root {
  --theme-surface: #f2dfae;
  --theme-surface-muted: #b68fa8;
  --theme-surface-disabled: #d5bf93;
  --theme-surface-deep: #384027;
  --theme-surface-raised: #f8ebc8;
  --theme-user-surface: #ddd3c2;
  --theme-user-accent: #786879;
  --theme-text-primary: #352817;
  --theme-text-secondary: #76551c;
  --theme-text-disabled: #5f513e;
  --theme-border: #a77724;
  --theme-focus-ring: #e0b848;
  --theme-focus-offset: 2px;
  --theme-opacity-disabled: 0.72;
  --theme-shadow: 0 8px 24px rgba(53, 40, 23, 0.18);
  --theme-info: #486e78;
  --theme-success: #526b3b;
  --theme-warning: #9a681f;
  --theme-error: #8a4238;
  --theme-code-surface: #303822;
  --theme-code-surface-inner: #39422a;
  --theme-code-text: #f4e4bd;
  --theme-code-muted: #b9aa88;
  --theme-code-semantic: #d5a85a;
  --theme-code-selection: #76551c;
  --ybtc-code-overflow: auto;
  --ybtc-topbar-object: none;
  --ybtc-checkbox-appearance: none;
  --ybtc-checkbox-display: inline-grid;
  --ybtc-font-body: "YBTC Source Han Serif SC", "Noto Serif CJK SC", "Songti SC", STSong, serif;
  --ybtc-font-display: "YBTC Huiwen Mincho", "YBTC Source Han Serif SC", "Songti SC", STSong, serif;
  --ybtc-radius-small: 8px;
  --ybtc-radius-medium: 14px;
  --ybtc-rule: 1px;
  --ybtc-shell-width: min(76vw, 1320px);
  --sheldWidth: var(--ybtc-shell-width);
  --ybtc-avatar-size: clamp(88px, 10.5vw, 156px);
  --ybtc-avatar-half-size: clamp(44px, 5.25vw, 78px);
  --ybtc-banner-max-inline-size: 920px;
  --ybtc-banner-inline-size: min(100cqi, var(--ybtc-banner-max-inline-size));
  --ybtc-banner-height: min(39.99cqi, 368px);
  --ybtc-banner-top-offset: 18px;
  --ybtc-banner-inline-gutter: calc((100cqi - var(--ybtc-banner-inline-size)) / 2);
  --ybtc-avatar-center-inline: min(83.45cqi, 768px);
  --ybtc-mobile-reading-width: 100%;
  --ybtc-mobile-reading-padding: clamp(18px, 5vw, 24px);
}

/* 只保护功能和数据，不在内核层定义审美构图。 */
#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons,
#send_form #leftSendForm,
#send_form #rightSendForm {
  pointer-events: auto;
}

#chat .mes_block,
#chat .mes_text,
#send_form #send_textarea {
  min-width: 0;
}

#chat .mes_text,
#chat .mes_reasoning,
.drawer-content {
  overflow-wrap: anywhere;
}

/* 只隐藏滚动条外观；不改变 overflow、触摸、指针或滚动节点。 */
:where(
  html,
  body,
  #sheld,
  #sheld *,
  #chat,
  #left-nav-panel,
  #left-nav-panel *,
  .drawer-content,
  .popup-content,
  .scrollable,
  .select2-results__options,
  #send_textarea,
  #chat .mes_text pre,
  #chat .mes_text .table-responsive
) {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

:where(
  html,
  body,
  #sheld,
  #sheld *,
  #chat,
  #left-nav-panel,
  #left-nav-panel *,
  .drawer-content,
  .popup-content,
  .scrollable,
  .select2-results__options,
  #send_textarea,
  #chat .mes_text pre,
  #chat .mes_text .table-responsive
)::-webkit-scrollbar {
  width: 0;
  height: 0;
}

/* 夜百合铜章主聊天：完整 Character 卷首、连续正文与独立 User 灰紫信笺。 */
#sheld {
  width: var(--ybtc-shell-width);
}

#chat {
  background-color: var(--theme-surface);
  background-image: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@3b5693bc6adf59779394a1ac3165d16eab651d18/assets/%E5%A4%9C%E7%99%BE%E5%90%88%E9%93%9C%E7%AB%A0/paper-texture.png");
  background-position: center top;
  background-repeat: repeat;
  background-size: 720px auto;
  border-inline: var(--ybtc-rule) solid var(--theme-border);
  color: var(--theme-text-primary);
  font-family: var(--ybtc-font-body);
  text-shadow: none;
}

#chat .mes {
  color: var(--theme-text-primary);
  font-family: var(--ybtc-font-body);
}

#chat .mes[is_user="false"][is_system="false"] {
  position: relative;
  container-type: inline-size;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  padding: clamp(10px, 1.4vw, 18px);
  background-color: transparent;
  background-image: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  filter: none;
  opacity: 1;
}

#chat .mes[is_user="false"][is_system="false"] > .mes_block,
#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
  grid-column: 1;
  grid-row: 1;
}

#chat .mes[is_user="false"][is_system="false"] > .for_checkbox,
#chat .mes[is_user="false"][is_system="false"] > .del_checkbox {
  grid-column: 1;
  grid-row: 1;
  align-self: start;
  justify-self: start;
  z-index: 4;
}

#chat .mes[is_user="false"][is_system="false"] > .mes_block {
  padding: 0;
  overflow-x: clip;
  overflow-y: visible;
}

/* 头像与投影片共用同一宽度基准；宽屏时先居中投影片，再计算太阳章中心。 */
#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
  align-self: start;
  justify-self: start;
  --ybtc-avatar-size: clamp(86px, 12cqi, 128px);
  --ybtc-avatar-half-size: calc(var(--ybtc-avatar-size) / 2);
  width: var(--ybtc-avatar-size);
  margin-block-start: calc(var(--ybtc-banner-top-offset) + var(--ybtc-banner-height) * 0.4855 - var(--ybtc-avatar-half-size));
  margin-inline-start: calc(var(--ybtc-banner-inline-gutter) + var(--ybtc-avatar-center-inline) - var(--ybtc-avatar-half-size));
  margin-inline-end: 0;
  padding: 0;
  z-index: 2;
}

#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .avatar,
#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .avatar img {
  box-sizing: border-box;
  width: var(--ybtc-avatar-size);
  height: var(--ybtc-avatar-size);
  border-radius: 50%;
}

#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .avatar {
  background: transparent;
  border: 0;
}

#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .avatar img {
  border: 5px double var(--theme-border);
  box-shadow: 0 0 0 2px var(--theme-surface-deep), 0 0 0 4px var(--theme-focus-ring);
  object-fit: cover;
  object-position: center;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
  position: relative;
  box-sizing: border-box;
  inline-size: var(--ybtc-banner-inline-size);
  max-inline-size: 100%;
  min-height: 0;
  block-size: var(--ybtc-banner-height);
  margin-block-start: var(--ybtc-banner-top-offset);
  margin-inline: auto;
  align-items: center;
  padding: 0;
  background-color: var(--theme-surface-deep);
  background-image: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@3b5693bc6adf59779394a1ac3165d16eab651d18/assets/%E5%A4%9C%E7%99%BE%E5%90%88%E9%93%9C%E7%AB%A0/character-banner.png");
  background-position: center;
  background-repeat: no-repeat;
  background-size: 100% 100%;
  border: 0;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container:first-child {
  align-self: stretch;
  align-items: center;
  min-width: 0;
}

/* 参考图为深色字心、金色描边，不再使用整块实心金字。 */
#chat .mes[is_user="false"][is_system="false"] .name_text {
  position: absolute;
  inset-inline-start: 40.5%;
  inset-block-start: 49%;
  transform: translate(-50%, -50%);
  color: var(--theme-text-primary);
  font-family: var(--ybtc-font-display);
  font-size: clamp(2.2rem, 4.6cqi, 3.6rem);
  font-weight: 400;
  line-height: 0.86;
  letter-spacing: 0.055em;
  inline-size: 36%;
  max-inline-size: 36%;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
  white-space: nowrap;
  -webkit-text-stroke: clamp(1px, 0.12vw, 2px) var(--theme-border);
  paint-order: stroke fill;
}

/* 真实时间放进相连饰带的左侧铭牌。 */
#chat .mes[is_user="false"][is_system="false"] .timestamp {
  position: absolute;
  inset-inline-start: 35%;
  inset-block-start: 84.5%;
  inset-block-end: auto;
  display: block;
  inline-size: 19%;
  color: var(--theme-text-secondary);
  font-size: clamp(0.56rem, 0.82cqi, 0.72rem);
  letter-spacing: 0.08em;
  margin: 0;
  text-align: center;
  transform: translate(-50%, -50%);
  white-space: nowrap;
}

#chat .mes[is_user="false"][is_system="false"] .timestamp::before {
  content: "✦ ";
}

/* 参考图中的下方直排文案是卷首装饰，不覆盖真实角色名、头像或时间。 */
#chat .mes[is_user="false"][is_system="false"] .ch_name::after {
  content: "夜色温柔，风也沉默。\A万物在梦里交换姓名。";
  position: absolute;
  inset-inline: 58% 16%;
  inset-block-start: 84%;
  inset-block-end: auto;
  color: var(--theme-text-primary);
  font-family: var(--ybtc-font-display);
  font-size: clamp(0.66rem, 1cqi, 0.94rem);
  line-height: 1.28;
  letter-spacing: 0.08em;
  text-align: center;
  transform: translateY(-50%);
  white-space: pre-line;
  pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_buttons,
#chat .mes[is_user="false"][is_system="false"] .mes_edit_buttons {
  position: absolute;
  inset-inline-start: 55%;
  inset-block-start: 17%;
  align-self: auto;
  margin-inline-end: 0;
  transform: translateX(-50%);
  z-index: 3;
}

#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .mesIDDisplay {
  position: absolute;
  inset-inline-start: calc(var(--ybtc-banner-inline-gutter) + min(25cqi, 260px));
  inset-block-start: calc(var(--ybtc-banner-top-offset) + var(--ybtc-banner-height) * 0.84);
  inline-size: min(18cqi, 187px);
  color: var(--theme-text-secondary);
  font-size: clamp(0.56rem, 0.82cqi, 0.72rem);
  letter-spacing: 0.08em;
  text-align: center;
  transform: translate(-50%, -50%);
  white-space: nowrap;
}

#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .mesIDDisplay:not(:empty)::before {
  content: "✦ 第 ";
}

#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .mesIDDisplay:not(:empty)::after {
  content: " 层 ✦";
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
  box-sizing: border-box;
  inline-size: var(--ybtc-banner-inline-size);
  max-inline-size: 100%;
  margin: clamp(6px, 0.8vw, 10px) auto 0;
  padding: clamp(22px, 3.4vw, 44px);
  background-color: var(--theme-surface-raised);
  background-image: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@3b5693bc6adf59779394a1ac3165d16eab651d18/assets/%E5%A4%9C%E7%99%BE%E5%90%88%E9%93%9C%E7%AB%A0/paper-texture.png");
  background-position: center top;
  background-repeat: repeat;
  background-size: 720px auto;
  border: var(--ybtc-rule) solid var(--theme-border);
  border-radius: var(--ybtc-radius-medium);
}

#chat .mes[is_user="false"][is_system="false"] .mes_text::after {
  content: "";
  display: block;
  min-height: clamp(74px, 10vw, 118px);
  margin-block-start: clamp(22px, 3vw, 38px);
  background-image: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@3b5693bc6adf59779394a1ac3165d16eab651d18/assets/%E5%A4%9C%E7%99%BE%E5%90%88%E9%93%9C%E7%AB%A0/footer-ribbon.png");
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  pointer-events: none;
}

/* User 输出使用参考图的浅灰紫信笺，不再继承官方深灰消息底。 */
#chat .mes[is_user="true"] {
  display: block;
  margin: clamp(8px, 1vw, 14px) clamp(10px, 1.4vw, 18px);
  padding: clamp(16px, 2.4vw, 28px) clamp(22px, 3vw, 40px);
  color: var(--theme-text-primary);
  background-color: var(--theme-user-surface);
  background-image: url("https://cdn.jsdelivr.net/gh/jiuyi777/sillytavern-theme-assets@3b5693bc6adf59779394a1ac3165d16eab651d18/assets/%E5%A4%9C%E7%99%BE%E5%90%88%E9%93%9C%E7%AB%A0/paper-texture.png");
  background-position: center;
  background-repeat: repeat;
  background-size: 720px auto;
  border: var(--ybtc-rule) solid var(--theme-border);
  border-radius: var(--ybtc-radius-medium);
  box-shadow: none;
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper {
  display: none;
}

#chat .mes[is_user="true"] > .mes_block {
  width: 100%;
  padding: 0;
}

#chat .mes[is_user="true"] .ch_name {
  color: var(--theme-user-accent);
  padding-block-end: 0.45em;
  border-bottom: var(--ybtc-rule) solid var(--theme-user-accent);
}

#chat .mes[is_user="true"] .ch_name::before {
  content: "\f52d";
  display: inline-block;
  margin-inline-end: 0.48em;
  font-family: "Font Awesome 6 Free";
  font-weight: 900;
  color: currentColor;
}

#chat .mes[is_user="true"] .name_text {
  color: var(--theme-user-accent);
  font-family: var(--ybtc-font-display);
  font-size: 1.28em;
  font-weight: 400;
  letter-spacing: 0.06em;
}

#chat .mes[is_user="true"] .timestamp {
  color: var(--theme-user-accent);
  font-size: 0.78em;
}

#chat .mes[is_user="true"] .mes_text {
  padding: 0.9em 0 0.25em clamp(16px, 2vw, 26px);
  background: transparent;
  border-inline-start: 2px solid var(--theme-user-accent);
}

#chat .mes[is_system="true"] {
  margin: 0.65em 1em;
  padding: 0.8em 1em;
  background-color: var(--theme-surface-disabled);
  border: var(--ybtc-rule) solid var(--theme-border);
  border-radius: var(--ybtc-radius-small);
}

#chat .mes .mesIDDisplay,
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay,
#chat .swipes-counter {
  color: var(--theme-text-secondary);
  font-family: var(--ybtc-font-body);
}

@media (max-width: 700px) {
  :root {
    --ybtc-shell-width: 100vw;
    --sheldWidth: 100vw;
    --ybtc-avatar-size: clamp(52px, 15vw, 64px);
    --ybtc-avatar-half-size: calc(var(--ybtc-avatar-size) / 2);
    --ybtc-banner-max-inline-size: 360px;
    --ybtc-banner-inline-size: min(100cqi, var(--ybtc-banner-max-inline-size));
    --ybtc-banner-height: min(39.99cqi, 144px);
    --ybtc-banner-top-offset: 10px;
    --ybtc-banner-inline-gutter: calc((100cqi - var(--ybtc-banner-inline-size)) / 2);
    --ybtc-avatar-center-inline: min(83.45cqi, 300px);
  }

  #sheld {
    width: 100vw;
  }

  #chat .mes[is_system="false"] {
    flex-direction: column;
    align-items: stretch;
  }

  #chat .mes[is_system="false"] > .mes_block {
    inline-size: 100%;
    min-inline-size: 0;
  }

  #chat .mes[is_system="false"] > .mes_block > .mes_text {
    inline-size: min(100%, var(--ybtc-mobile-reading-width));
    max-inline-size: 100%;
    margin-inline: auto !important;
    padding-inline: var(--ybtc-mobile-reading-padding) !important;
    box-sizing: border-box;
  }

  #chat .mes[is_user="false"][is_system="false"] {
    padding: 7px;
  }

  #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
    --ybtc-avatar-size: clamp(58px, 17cqi, 72px);
    --ybtc-avatar-half-size: calc(var(--ybtc-avatar-size) / 2);
    margin-block-start: calc(var(--ybtc-banner-top-offset) + var(--ybtc-banner-height) * 0.4855 - var(--ybtc-avatar-half-size));
  }

  #chat .mes[is_user="false"][is_system="false"] .ch_name {
    padding: 0;
  }

  #chat .mes[is_user="false"][is_system="false"] .name_text {
    font-size: clamp(1.35rem, 6.5vw, 2rem);
    letter-spacing: 0.02em;
  }

  #chat .mes[is_user="false"][is_system="false"] .timestamp {
    inset-inline-start: 35%;
    inset-block-start: 84.5%;
    inset-block-end: auto;
    font-size: 0.58em;
  }

  #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper .mesIDDisplay {
    inset-inline-start: calc(var(--ybtc-banner-inline-gutter) + min(25cqi, 160px));
    inset-block-start: calc(var(--ybtc-banner-height) * 0.84);
    font-size: 0.52em;
  }

  #chat .mes[is_user="false"][is_system="false"] .ch_name::after {
    inset-inline: 58% 16%;
    inset-block-start: 84%;
    inset-block-end: auto;
    font-size: clamp(0.46rem, 2vw, 0.62rem);
  }

  #chat .mes[is_user="false"][is_system="false"] .mes_buttons,
  #chat .mes[is_user="false"][is_system="false"] .mes_edit_buttons {
    margin-inline-end: 0;
  }

  #chat .mes[is_user="false"][is_system="false"] .mes_text {
    inline-size: min(100%, var(--ybtc-banner-inline-size));
    margin-inline: auto !important;
    padding: clamp(18px, 5vw, 24px);
  }

  #chat .mes[is_user="true"] {
    margin-inline: 7px;
    padding: 15px 18px;
  }
}

/* T01 传统小说：继承用户字号，不以固定 px 覆盖正文。 */
#chat .mes_text {
  color: var(--theme-text-primary);
  font-family: var(--ybtc-font-body);
  font-size: 1em;
  font-weight: 400;
  line-height: 1.95;
  letter-spacing: 0.035em;
}

#chat .mes_text p {
  margin: 0 0 0.9em;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
  color: var(--theme-text-secondary);
  font-family: var(--ybtc-font-display);
  font-weight: 400;
  line-height: 1.35;
  letter-spacing: 0.08em;
}

#chat .mes_text strong,
#chat .mes_text b {
  color: var(--theme-text-secondary);
  font-weight: 400;
  letter-spacing: 0.06em;
}

#chat .mes_text em,
#chat .mes_text i,
#chat .mes_text q {
  color: var(--theme-text-secondary);
}

#chat .mes_text blockquote {
  margin: 1em 0;
  padding: 0.65em 1em;
  background-color: var(--theme-surface-disabled);
  border-left: 3px solid var(--theme-surface-muted);
}

#chat .mes_text :not(pre) > code {
  color: var(--theme-text-primary);
  background-color: var(--theme-surface-disabled);
  border: var(--ybtc-rule) solid var(--theme-border);
  border-radius: var(--ybtc-radius-small);
  padding-inline: 0.28em;
  text-shadow: none;
}

#chat .mes_text pre {
  position: relative;
  overflow-x: var(--ybtc-code-overflow);
  color: var(--theme-code-text);
  background-color: var(--theme-code-surface);
  border: var(--ybtc-rule) solid var(--theme-border);
  border-radius: var(--ybtc-radius-small);
  box-shadow: none;
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#chat .mes_text pre code.hljs {
