  background-size: 720px auto;
  color: var(--theme-text-primary);
  border: var(--ybtc-rule) solid var(--theme-border);
  border-radius: var(--ybtc-radius-medium);
}

#send_form #send_textarea {
  color: var(--theme-text-primary);
  background-color: transparent;
  caret-color: var(--theme-text-secondary);
  font-family: var(--ybtc-font-body);
  font-size: 1em;
}

#send_form #send_textarea::placeholder {
  color: var(--theme-text-disabled);
}

#send_form #options_button,
#send_form #extensionsMenuButton,
#send_form #send_but,
#send_form #mes_stop {
  color: var(--theme-text-secondary);
  background-color: var(--theme-surface);
  border: var(--ybtc-rule) solid var(--theme-border);
  border-radius: 50%;
  opacity: 1;
}

#send_form #options_button:hover,
#send_form #extensionsMenuButton:hover,
#send_form #send_but:hover,
#send_form #mes_stop:hover {
  color: var(--theme-surface-raised);
  background-color: var(--theme-surface-deep);
  filter: none;
}

#send_form.no-connection #send_but,
#send_form [aria-disabled="true"],
#send_form .disabled {
  color: var(--theme-text-disabled);
  background-color: var(--theme-surface-disabled);
  opacity: var(--theme-opacity-disabled);
}

#send_form #options_button:focus-visible,
#send_form #extensionsMenuButton:focus-visible,
#send_form #send_but:focus-visible,
#send_form #mes_stop:focus-visible,
#send_form #send_textarea:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: var(--theme-focus-offset);
}

@media (max-width: 700px) {
  #send_form #nonQRFormItems {
    flex-wrap: nowrap;
  }

  #send_form #leftSendForm,
  #send_form #rightSendForm {
    flex-wrap: nowrap;
    flex: 0 0 auto;
  }

  #send_form #send_textarea {
    min-width: 0;
    flex: 1 1 auto;
  }
}

/* 图片、字体失败时仍保持纸色、边框、真实文字与原生交互。 */
@media (prefers-reduced-motion: reduce) {
  #chat,
  #send_form,
  .drawer-content {
    scroll-behavior: auto;
  }
}

@supports not (overflow: clip) {
  #chat .mes[is_user="false"][is_system="false"] > .mes_block {
    overflow-x: hidden;
  }
}
